export type SyncErrorCode = "AUTHENTICATION_REQUIRED" | "DEVICE_CREDENTIAL_REVOKED" | "DEVICE_CREDENTIAL_EXPIRED" | "USER_INACTIVE" | "SPACE_FORBIDDEN" | "SPACE_READ_ONLY" | "INSTALLATION_NOT_FOUND" | "INSTALLATION_REVOKED" | "INSTALLATION_ALREADY_EXCHANGED" | "INSTALLATION_CODE_INVALID" | "INSTALLATION_CODE_EXPIRED" | "CREDENTIAL_COLLISION" | "PROTOCOL_UNSUPPORTED" | "REVISION_GONE" | "CURSOR_INVALID" | "BASE_STALE" | "CONFIRMATION_REQUIRED" | "CONFIRMATION_MISMATCH" | "PAYLOAD_INVALID" | "PATH_COLLISION" | "PAGE_ID_CONFLICT" | "PAGE_TOO_LARGE" | "BATCH_TOO_LARGE" | "SPACE_TOO_LARGE" | "BATCH_MISMATCH" | "PUSH_SESSION_EXPIRED" | "PUSH_SESSION_NOT_FOUND" | "PUSH_SESSION_STATE_INVALID" | "PUSH_SESSION_INCOMPLETE" | "IDEMPOTENCY_MISMATCH" | "CAPABILITIES_CHANGED" | "QUOTA_EXCEEDED" | "RATE_LIMITED" | "INTERNAL_ERROR";
